// Project data stores absolute URLs (the prerender script and llms.txt need
// them), but a link to a page of THIS site should stay on this site — and on
// localhost it must not jump to the deployed copy. Same-site absolute URLs
// become root-relative paths; everything else is returned untouched.
const SITE_ORIGINS = [
  "https://laxman824.github.io",
  "http://laxman824.github.io",
];

export default function siteHref(url) {
  if (!url || typeof url !== "string") return url;
  const origin = SITE_ORIGINS.find((o) => url.startsWith(o + "/") || url === o);
  if (!origin) return url;
  const path = url.slice(origin.length) || "/";
  // static sub-sites (public/opennotch/) still need a full page load, which a
  // plain relative href gives them.
  return path;
}
